insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei regulamenta o disposto no inciso XLIII do art. 5º da Constituição, disciplinando o terrorismo, tratando de disposições investigatórias e processuais e reformulando o conceito de organização terrorista.', '["Regulamenta o inciso XLIII do art. 5º da Constituição.","Disciplina o terrorismo.","Traz disposições investigatórias e processuais.","Reformula o conceito de organização terrorista."]'::jsonb, '["O inciso XLIII da Constituição trata do terrorismo como crime inafiançável e insuscetível de graça ou anistia."]'::jsonb, 'A lei concretiza o mandado constitucional de criminalização do terrorismo.', '["Assertiva que restringe a lei ao aspecto penal, sem disposições processuais e investigatórias, erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O terrorismo consiste na prática por um ou mais indivíduos dos atos previstos no artigo, por razões de xenofobia, discriminação ou preconceito de raça, cor, etnia e religião, quando cometidos com a finalidade de provocar terror social ou generalizado, expondo a perigo pessoa, patrimônio, a paz pública ou a incolumidade pública. São atos de terrorismo usar ou ameaçar usar, transportar, guardar, portar ou trazer consigo explosivos, gases tóxicos, venenos, conteúdos biológicos, químicos, nucleares ou outros meios capazes de causar danos ou destruição em massa; sabotar o funcionamento ou apoderar-se, com violência, grave ameaça ou por mecanismos cibernéticos, do controle total ou parcial, ainda que temporário, de meios de comunicação ou de transporte, portos, aeroportos, estações, hospitais, escolas, estádios, instalações públicas ou de serviços essenciais, de energia, militares, de petróleo e gás e instituições bancárias; e atentar contra a vida ou a integridade física de pessoa. Pena: reclusão de doze a trinta anos, além das sanções correspondentes à ameaça ou à violência. A lei não se aplica à conduta de pessoas em manifestações políticas, movimentos sociais, sindicais, religiosos, de classe ou de categoria profissional, com propósitos sociais ou reivindicatórios, para contestar, criticar, protestar ou apoiar, com o objetivo de defender direitos, garantias e liberdades constitucionais.', '["Motivação: xenofobia, discriminação ou preconceito de raça, cor, etnia e religião.","Finalidade: provocar terror social ou generalizado.","Atos: explosivos e meios de destruição em massa; sabotagem ou controle de meios de comunicação, transporte e instalações essenciais; atentado contra a vida ou a integridade física.","Pena: reclusão de doze a trinta anos, além das sanções da ameaça ou violência.","Excludente: manifestações políticas e movimentos sociais com propósitos reivindicatórios."]'::jsonb, '["Exige motivação DISCRIMINATÓRIA (xenofobia, raça, cor, etnia ou religião) e FINALIDADE de terror social.","Motivação política ou ideológica NÃO está no tipo.","Os incisos II e III foram vetados.","Movimentos sociais são excluídos do conceito."]'::jsonb, 'Ataque com explosivos a um templo religioso, para causar terror social por preconceito religioso, é terrorismo.', '["Assertiva que inclui a motivação política como elemento do terrorismo erra: o tipo exige xenofobia, discriminação ou preconceito de raça, cor, etnia ou religião."]'::jsonb, '[{"termo":"Terror social ou generalizado","significado":"Finalidade de infundir medo coletivo."}]'::jsonb, '["Art. 1º","Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Promover, constituir, integrar ou prestar auxílio, pessoalmente ou por interposta pessoa, a organização terrorista. Pena: reclusão de cinco a oito anos e multa.', '["Promover, constituir, integrar ou auxiliar organização terrorista.","Pessoalmente ou por interposta pessoa.","Reclusão de cinco a oito anos e multa."]'::jsonb, '["Crime autônomo, de natureza associativa.","Os §§ 1º e 2º foram vetados."]'::jsonb, 'Quem integra grupo organizado para praticar atos de terrorismo responde pelo art. 3º.', '["Assertiva que aplica a mesma pena do terrorismo (doze a trinta anos) à participação em organização terrorista erra: é de cinco a oito anos."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Realizar atos preparatórios de terrorismo com o propósito inequívoco de consumar tal delito. Pena: a correspondente ao delito consumado, diminuída de um quarto até a metade. Incorre nas mesmas penas o agente que, com o propósito de praticar atos de terrorismo, recruta, organiza, transporta ou municia indivíduos que viajem para país distinto daquele de sua residência ou nacionalidade, ou fornece ou recebe treinamento em país distinto. Quando a conduta não envolver treinamento ou viagem para país distinto, a pena será a do delito consumado, diminuída de metade a dois terços.', '["Atos preparatórios com propósito inequívoco de consumar o terrorismo.","Pena do consumado diminuída de 1/4 até a metade.","Recrutar, organizar, transportar ou municiar indivíduos que viajem; fornecer ou receber treinamento no exterior.","Sem viagem ou treinamento no exterior: diminuição de metade a 2/3."]'::jsonb, '["Punição EXCEPCIONAL de ato preparatório.","Exige propósito INEQUÍVOCO de consumar o terrorismo."]'::jsonb, 'Quem recebe treinamento no exterior para praticar atos de terrorismo pratica o crime do art. 5º.', '["Assertiva que pune qualquer ato preparatório sem exigir propósito inequívoco erra."]'::jsonb, '[{"termo":"Ato preparatório","significado":"Conduta anterior à execução, em regra impunível, mas punida aqui por exceção."}]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Receber, prover, oferecer, obter, guardar, manter em depósito, solicitar, investir, de qualquer modo, direta ou indiretamente, recursos, ativos, bens, direitos, valores ou serviços de qualquer natureza, para o planejamento, a preparação ou a execução dos crimes previstos na Lei. Pena: reclusão de quinze a trinta anos. Incorre na mesma pena quem oferecer, receber, obter, guardar, mantiver em depósito, solicitar, investir ou de qualquer modo contribuir para a obtenção de ativo, bem ou recurso financeiro, com a finalidade de financiar, total ou parcialmente, pessoa, grupo, associação, entidade ou organização criminosa que tenha como atividade principal ou secundária, mesmo em caráter eventual, a prática dos crimes da Lei.', '["Financiamento do terrorismo em sentido amplo.","Reclusão de quinze a trinta anos.","Também financiar organização que pratique terrorismo, mesmo em caráter eventual."]'::jsonb, '["Pena do financiamento (quinze a trinta anos) é MAIOR que a do próprio terrorismo (doze a trinta anos).","Financiar organização atinge quem apoia, ainda que o apoio seja eventual."]'::jsonb, 'Quem doa recursos a grupo para planejar atentado responde pelo art. 6º.', '["Assertiva que fixa a pena do financiamento em reclusão de doze a trinta anos erra: é de quinze a trinta anos."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo quando for elementar da prática de qualquer crime previsto na Lei, se de algum deles resultar lesão corporal grave, aumenta-se a pena de um terço; se resultar morte, aumenta-se a pena da metade.', '["Lesão corporal grave: aumento de um terço.","Morte: aumento da metade.","Não se aplica se o resultado for elementar do crime."]'::jsonb, '["Evita bis in idem quando o resultado já é elementar do tipo."]'::jsonb, 'Do ato de terrorismo resulta morte não prevista como elementar: pena aumentada da metade.', '["Assertiva que aumenta a pena em dobro quando há morte erra: é aumentada da metade."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Mesmo antes de iniciada a execução do crime de terrorismo, na hipótese do art. 5º da Lei (atos preparatórios), aplicam-se as disposições do art. 15 do Código Penal (desistência voluntária e arrependimento eficaz).', '["Atos preparatórios do art. 5º admitem a desistência voluntária e o arrependimento eficaz.","Aplica-se o art. 15 do Código Penal."]'::jsonb, '["Mesmo antes do início da execução."]'::jsonb, 'Quem, durante os atos preparatórios, desiste voluntariamente, responde só pelos atos já praticados.', '["Assertiva que afasta a desistência voluntária nos atos preparatórios do terrorismo erra."]'::jsonb, '[{"termo":"Desistência voluntária","significado":"O agente interrompe voluntariamente a execução e responde só pelo já praticado."}]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para todos os efeitos legais, considera-se que os crimes previstos na Lei são praticados contra o interesse da União, cabendo à Polícia Federal a investigação criminal, em sede de inquérito policial, e à Justiça Federal o seu processamento e julgamento, nos termos do inciso IV do art. 109 da Constituição.', '["Crimes presumidos contra o interesse da União.","Investigação pela Polícia Federal, em inquérito policial.","Processo e julgamento pela Justiça Federal."]'::jsonb, '["Competência da POLÍCIA FEDERAL e da JUSTIÇA FEDERAL."]'::jsonb, 'Um atentado terrorista é investigado pela Polícia Federal e julgado pela Justiça Federal.', '["Assertiva que atribui à Polícia Civil a investigação do terrorismo erra: é da Polícia Federal."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, de ofício, a requerimento do Ministério Público ou mediante representação do delegado de polícia, ouvido o Ministério Público em vinte e quatro horas, havendo indícios suficientes de crime previsto na Lei, poderá decretar, no curso da investigação ou da ação penal, medidas assecuratórias de bens, direitos ou valores do investigado ou acusado, ou existentes em nome de interpostas pessoas, que sejam instrumento, produto ou proveito dos crimes. Proceder-se-á à alienação antecipada para preservação do valor dos bens sujeitos a deterioração ou depreciação. O juiz determinará a liberação, total ou parcial, dos bens quando comprovada a licitude de sua origem e destinação, mantendo a constrição necessária à reparação dos danos, prestações pecuniárias, multas e custas. Nenhum pedido de liberação será conhecido sem o comparecimento pessoal do acusado ou de interposta pessoa. Poderão ser decretadas medidas assecuratórias para reparação do dano ou pagamento de prestação pecuniária, multa e custas.', '["Medidas assecuratórias de bens, decretadas de ofício, a pedido do MP ou por representação do delegado.","MP ouvido em vinte e quatro horas.","Havendo indícios suficientes do crime.","Alienação antecipada de bens que se deterioram.","Liberação se comprovada a licitude da origem e da destinação.","Pedido de liberação exige comparecimento pessoal."]'::jsonb, '["Bens em nome de INTERPOSTAS pessoas também podem ser atingidos.","Prazo de vinte e quatro horas para a oitiva do MP."]'::jsonb, 'O juiz sequestra bens do investigado registrados em nome de um laranja.', '["Assertiva que dispensa o comparecimento pessoal do acusado para o pedido de liberação de bens erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'terrorismo' and u.unit_key = 'art-12'
