insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando as circunstâncias o aconselharem, o juiz, ouvido o Ministério Público, nomeará pessoa física ou jurídica qualificada para a administração dos bens, direitos ou valores sujeitos a medidas assecuratórias, mediante termo de compromisso.', '["Juiz pode nomear administrador qualificado para os bens constritos.","Ouvido o MP e mediante termo de compromisso."]'::jsonb, '["Nomeação facultativa, conforme as circunstâncias."]'::jsonb, 'O juiz nomeia uma empresa qualificada para administrar um negócio sequestrado.', '["Assertiva que dispensa a oitiva do MP para nomear o administrador dos bens erra."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
