insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz determinará, na hipótese de existência de tratado ou convenção internacional e por solicitação de autoridade estrangeira competente, medidas assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos na Lei praticados no estrangeiro. Aplica-se o disposto, independentemente de tratado ou convenção, quando houver reciprocidade do governo do país solicitante. Na falta de tratado ou convenção, os bens ou os recursos provenientes da sua alienação serão repartidos entre o Estado requerente e o Brasil, na proporção de metade, ressalvado o direito do lesado ou de terceiro de boa-fé.', '["Cooperação internacional: medidas assecuratórias sobre bens de crimes praticados no exterior.","Com tratado, ou sem tratado, havendo reciprocidade.","Sem tratado: partilha de metade entre o Estado requerente e o Brasil."]'::jsonb, '["Reciprocidade dispensa o tratado.","Partilha na proporção de METADE."]'::jsonb, 'A pedido de país estrangeiro, o juiz bloqueia bens ligados a um atentado praticado lá.', '["Assertiva que exige sempre tratado para a cooperação em medidas assecuratórias erra: basta a reciprocidade."]'::jsonb, '[{"termo":"Reciprocidade","significado":"Compromisso de o país solicitante agir igualmente com o Brasil."}]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
