insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao Sinarm compete identificar as características e a propriedade de armas de fogo, mediante cadastro; cadastrar as armas produzidas, importadas e vendidas no País; cadastrar as autorizações de porte e as renovações expedidas pela Polícia Federal; cadastrar as transferências de propriedade, extravio, furto, roubo e outras ocorrências; identificar as modificações que alterem as características ou o funcionamento; integrar no cadastro os acervos policiais; cadastrar as apreensões; cadastrar os armeiros e conceder licença para a atividade; cadastrar mediante registro produtores, atacadistas, varejistas, exportadores e importadores autorizados; cadastrar a identificação do cano e as características das impressões de raiamento e microestriamento do projétil; entre outras competências.', '["Cadastro das armas produzidas, importadas e vendidas.","Cadastro das autorizações de porte e renovações.","Cadastro de ocorrências: transferência, extravio, furto, roubo, apreensões.","Licença e cadastro de armeiros.","Registro de produtores, comerciantes, exportadores e importadores.","Cadastro do cano e das características balísticas."]'::jsonb, '["O Sinarm CADASTRA e identifica; a concessão do porte é da Polícia Federal."]'::jsonb, 'A apreensão de uma arma em operação policial é cadastrada no Sinarm.', '["Assertiva que atribui ao Sinarm a produção e a venda das armas erra: ele as cadastra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
