insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatório o registro de arma de fogo no órgão competente. As armas de fogo de uso restrito serão registradas no Comando do Exército, na forma do regulamento da Lei.', '["Registro obrigatório.","Uso permitido: Polícia Federal (Sinarm).","Uso restrito: Comando do Exército."]'::jsonb, '["Registro de arma de USO RESTRITO: Comando do Exército."]'::jsonb, 'Um fuzil de uso restrito é registrado no Comando do Exército.', '["Assertiva que atribui à Polícia Federal o registro das armas de uso restrito erra: é do Comando do Exército."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
