on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para adquirir arma de fogo de uso permitido, o interessado deverá, além de declarar a efetiva necessidade, comprovar idoneidade, com certidões negativas de antecedentes criminais das Justiças Federal, Estadual, Militar e Eleitoral e de não estar respondendo a inquérito policial ou processo criminal; apresentar documento comprobatório de ocupação lícita e de residência certa; e comprovar capacidade técnica e aptidão psicológica para o manuseio de arma de fogo. O Sinarm expedirá autorização de compra em nome do requerente e para a arma indicada, intransferível. A aquisição de munição só poderá ser feita no calibre correspondente à arma registrada e na quantidade estabelecida no regulamento. A empresa que comercializar arma de fogo é obrigada a comunicar a venda à autoridade competente.', '["Declaração de efetiva necessidade.","Idoneidade: certidões negativas e inexistência de inquérito ou processo.","Ocupação lícita e residência certa.","Capacidade técnica e aptidão psicológica.","Autorização de compra intransferível.","Munição: calibre da arma registrada e quantidade regulamentar."]'::jsonb, '["ATUALIZAÇÃO: redação do inciso I dada pela Lei nº 11.706, de 2008; o texto remete a ADIs sobre a aquisição de munição (ADI 6466 e ADI 6139).","A efetiva necessidade e os requisitos são cumulativos."]'::jsonb, 'Quem responde a processo criminal não preenche o requisito de idoneidade para comprar arma.', '["Assertiva que dispensa a aptidão psicológica para adquirir arma de fogo de uso permitido erra."]'::jsonb, '[]'::jsonb, '["Art. 5º","Art. 10"]'::jsonb, 'under_review', 'claude'
