on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O certificado de Registro de Arma de Fogo, com validade em todo o território nacional, autoriza o proprietário a manter a arma de fogo exclusivamente no interior de sua residência ou domicílio, ou dependência desses, ou no seu local de trabalho, desde que seja ele o titular ou o responsável legal pelo estabelecimento ou empresa. O certificado será expedido pela Polícia Federal e precedido de autorização do Sinarm. Os requisitos dos incisos I, II e III do art. 4º devem ser comprovados periodicamente, em período não inferior a 3 anos, para a renovação do certificado. O proprietário de arma com registro estadual anterior que não optasse pela entrega espontânea deveria renová-lo no registro federal até o dia 31 de dezembro de 2008.', '["Registro autoriza manter a arma NA RESIDÊNCIA ou no local de trabalho (titular ou responsável).","Expedido pela Polícia Federal, após autorização do Sinarm.","Renovação com comprovação periódica dos requisitos, em período não inferior a 3 anos.","Registro estadual antigo: renovação federal até 31 de dezembro de 2008."]'::jsonb, '["O REGISTRO não autoriza portar a arma fora de casa; isso exige o PORTE.","Renovação: não inferior a 3 anos."]'::jsonb, 'O dono de arma registrada pode guardá-la em casa, mas não levá-la na rua sem porte.', '["Assertiva que permite ao titular do registro portar a arma em vias públicas erra: o registro autoriza mantê-la na residência ou no local de trabalho."]'::jsonb, '[{"termo":"Posse","significado":"Manter a arma em casa ou no local de trabalho, com registro."}]'::jsonb, '["Art. 6º","Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibido o porte de arma de fogo em todo o território nacional, salvo para os casos previstos em legislação própria e para os integrantes das Forças Armadas; dos órgãos referidos nos incisos I a V do art. 144 da Constituição e da Força Nacional de Segurança Pública; das guardas municipais, nas condições do regulamento; dos agentes operacionais da ABIN e do Departamento de Segurança do GSI; das polícias legislativas; dos agentes e guardas prisionais, das escoltas de presos e das guardas portuárias; das empresas de segurança privada e de transporte de valores; das entidades de desporto cujas atividades demandem armas de fogo; das carreiras de Auditoria da Receita Federal e de Auditoria-Fiscal do Trabalho; e dos tribunais e Ministérios Públicos, para servidores que exerçam funções de segurança. Integrantes de certas categorias podem portar mesmo fora de serviço. A autorização para guardas municipais depende de formação funcional, fiscalização e controle interno. Residentes em áreas rurais, maiores de 25 anos, que dependam da arma para subsistência alimentar, podem obter o porte na categoria caçador para subsistência. Guardas municipais de Municípios integrantes de regiões metropolitanas têm porte quando em serviço.', '["Regra: porte PROIBIDO.","Exceções: Forças Armadas, órgãos de segurança do art. 144, Força Nacional, ABIN e GSI, polícias legislativas, agentes prisionais, escoltas, guardas portuárias, empresas de segurança privada, entidades desportivas, Receita e auditores do trabalho, tribunais e MPs (segurança).","Guardas municipais: nas condições do regulamento, com formação e fiscalização.","Caçador para subsistência: rural, maior de 25 anos, arma de uso permitido, tiro simples.","Uso fora de serviço para integrantes de certas categorias."]'::jsonb, '["ATUALIZAÇÃO: inciso VI com redação da Lei nº 15.306, de 2025 (polícias legislativas); partes do dispositivo foram declaradas inconstitucionais pelo STF (ADI 5538) quanto às guardas municipais.","Porte é EXCEÇÃO à proibição geral.","O caçador para subsistência que der outro uso à arma responde por porte ilegal ou disparo."]'::jsonb, 'O policial civil pode portar arma fora de serviço, nos termos do regulamento.', '["Assertiva que torna o porte de arma regra geral para qualquer cidadão com registro erra: o porte é proibido, salvo exceções legais."]'::jsonb, '[{"termo":"Caçador para subsistência","significado":"Categoria de porte para quem depende da arma para o sustento familiar na zona rural."}]'::jsonb, '["Art. 10","Art. 14"]'::jsonb, 'under_review', 'claude'
