insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As armas de fogo utilizadas pelos profissionais de segurança privada dos prestadores de serviços e das empresas e condomínios com serviços orgânicos de segurança privada serão de propriedade, responsabilidade e guarda das respectivas empresas, somente podendo ser utilizadas quando em serviço, observadas as condições de uso e armazenagem estabelecidas pelo órgão competente, sendo o certificado de registro e a autorização de porte expedidos pela Polícia Federal em nome da empresa. O proprietário ou diretor responsável de empresa de segurança privada e de transporte de valores responderá pelo crime do parágrafo único do art. 13, sem prejuízo das demais sanções, se deixar de registrar ocorrência e comunicar à Polícia Federal perda, furto, roubo ou outra forma de extravio de armas, acessórios e munições sob sua guarda nas primeiras 24 horas depois de ocorrido o fato.', '["Armas da segurança privada pertencem às empresas e só são usadas em serviço.","Registro e porte em nome da empresa, expedidos pela Polícia Federal.","Comunicar perda, furto ou roubo à PF e à polícia em 24 horas, sob pena do art. 13, parágrafo único."]'::jsonb, '["ATUALIZAÇÃO: redação do caput dada pela Lei nº 14.967, de 2024 (Estatuto da Segurança Privada).","Prazo de 24 horas para comunicar extravio."]'::jsonb, 'A empresa de vigilância comunica à PF, em 24 horas, o roubo de uma arma sob sua guarda.', '["Assertiva que atribui ao vigilante a propriedade da arma usada em serviço erra: é da empresa."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As armas de fogo utilizadas pelos servidores dos tribunais e Ministérios Públicos (instituições do inciso XI do art. 6º) serão de propriedade, responsabilidade e guarda das respectivas instituições, somente podendo ser utilizadas quando em serviço, sendo o certificado de registro e a autorização de porte expedidos pela Polícia Federal em nome da instituição. A autorização independe de pagamento de taxa. O presidente do tribunal ou o chefe do Ministério Público designará os servidores com funções de segurança que poderão portar arma, respeitado o limite máximo de 50% dos servidores que exerçam essas funções. O porte fica condicionado à comprovação dos requisitos do art. 4º, à formação funcional em estabelecimentos de ensino policial e à existência de mecanismos de fiscalização e controle interno.', '["Armas pertencem às instituições e só são usadas em serviço.","Porte em nome da instituição, sem taxa.","Limite de 50% dos servidores que exerçam funções de segurança.","Condições: requisitos do art. 4º, formação policial e controle interno."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.694, de 2012; há questionamento no STF (ADI 5157).","Limite de 50% dos servidores de segurança."]'::jsonb, 'O tribunal designa parte dos seus agentes de segurança para portar arma, respeitado o teto de 50%.', '["Assertiva que permite o porte de arma a todos os servidores de segurança do tribunal erra: há teto de 50%."]'::jsonb, '[]'::jsonb, '["Art. 6º, XI"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-7-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As armas de fogo utilizadas em entidades desportivas legalmente constituídas devem obedecer às condições de uso e de armazenagem estabelecidas pelo órgão competente, respondendo o possuidor ou o autorizado a portar a arma pela sua guarda, na forma do regulamento.', '["Armas das entidades desportivas seguem as condições de uso e armazenagem do órgão competente.","O possuidor ou autorizado responde pela guarda."]'::jsonb, '["Responsabilidade pela GUARDA recai sobre o possuidor ou autorizado."]'::jsonb, 'O clube de tiro guarda as armas conforme as normas do órgão competente.', '["Assertiva que isenta o possuidor da responsabilidade pela guarda da arma da entidade desportiva erra."]'::jsonb, '[]'::jsonb, '["Art. 6º, IX"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Ministério da Justiça a autorização do porte de arma para os responsáveis pela segurança de cidadãos estrangeiros em visita ou sediados no Brasil e, ao Comando do Exército, nos termos do regulamento, o registro e a concessão de porte de trânsito de arma de fogo para colecionadores, atiradores e caçadores e de representantes estrangeiros em competição internacional oficial de tiro realizada no território nacional.', '["Ministério da Justiça: porte para quem faz a segurança de estrangeiros.","Comando do Exército: registro e porte de trânsito para colecionadores, atiradores e caçadores (CAC) e competidores estrangeiros."]'::jsonb, '["Os CAC têm registro e porte de TRÂNSITO concedidos pelo EXÉRCITO."]'::jsonb, 'O atirador desportivo obtém porte de trânsito no Comando do Exército.', '["Assertiva que atribui à Polícia Federal o registro dos colecionadores, atiradores e caçadores erra: é do Comando do Exército."]'::jsonb, '[{"termo":"CAC","significado":"Colecionadores, atiradores desportivos e caçadores."}]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autorização para o porte de arma de fogo de uso permitido, em todo o território nacional, é de competência da Polícia Federal e somente será concedida após autorização do Sinarm. Poderá ser concedida com eficácia temporária e territorial limitada, nos termos de atos regulamentares, e dependerá de o requerente demonstrar a sua efetiva necessidade por exercício de atividade profissional de risco ou de ameaça à sua integridade física; atender às exigências do art. 4º; e apresentar documentação de propriedade da arma, bem como seu registro. A autorização perderá automaticamente sua eficácia caso o portador seja detido ou abordado em estado de embriaguez ou sob efeito de substâncias químicas ou alucinógenas.', '["Porte de arma de uso permitido: competência da Polícia Federal, após autorização do Sinarm.","Eficácia temporária e territorial limitada.","Requisitos: efetiva necessidade (atividade profissional de risco ou ameaça), requisitos do art. 4º, documentação e registro.","Perde a eficácia se o portador estiver embriagado ou sob efeito de drogas."]'::jsonb, '["Perda AUTOMÁTICA da autorização em caso de embriaguez ou drogas.","Porte é competência da POLÍCIA FEDERAL."]'::jsonb, 'Portador de arma abordado embriagado perde automaticamente o porte.', '["Assertiva que exige decisão judicial para a perda da eficácia do porte em caso de embriaguez erra: a perda é automática."]'::jsonb, '[]'::jsonb, '["Art. 4º","Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica instituída a cobrança de taxas, nos valores do Anexo da Lei, pela prestação de serviços relativos ao registro de arma de fogo, à renovação de registro, à expedição de segunda via de registro, à expedição de porte federal, à renovação de porte e à expedição de segunda via de porte federal. Os valores arrecadados destinam-se ao custeio e à manutenção das atividades do Sinarm, da Polícia Federal e do Comando do Exército. São isentas as pessoas e instituições referidas nos incisos I a VII e X e no §5º do art. 6º.', '["Taxas para registro, renovação, segunda via e porte federal.","Valores destinam-se ao Sinarm, à Polícia Federal e ao Comando do Exército.","Isenção para as categorias listadas do art. 6º."]'::jsonb, '["Valores no Anexo da lei."]'::jsonb, 'O cidadão paga taxa para expedir o porte federal, enquanto as Forças Armadas são isentas.', '["Assertiva que cobra taxas dos integrantes das Forças Armadas na expedição do porte erra: eles são isentos."]'::jsonb, '[]'::jsonb, '["Anexo"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério da Justiça disciplinará a forma e as condições do credenciamento de profissionais pela Polícia Federal para comprovação da aptidão psicológica e da capacidade técnica para o manuseio de arma de fogo. O valor cobrado pelo psicólogo não poderá exceder o valor médio dos honorários para avaliação psicológica da tabela do Conselho Federal de Psicologia. O valor cobrado pelo instrutor de armamento e tiro não poderá exceder R$ 80,00, acrescido do custo da munição. A cobrança de valores superiores implicará o descredenciamento do profissional pela Polícia Federal.', '["Credenciamento de psicólogos e instrutores pela Polícia Federal.","Teto de honorários do psicólogo: valor médio da tabela do CFP.","Teto do instrutor: R$ 80,00, mais o custo da munição.","Cobrança acima do teto: descredenciamento."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 11.706, de 2008."]'::jsonb, 'Instrutor que cobra acima do limite legal é descredenciado pela Polícia Federal.', '["Assertiva que permite ao instrutor cobrar livremente pela avaliação de capacidade técnica erra: há teto legal."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-11-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Posse irregular de arma de fogo de uso permitido: possuir ou manter sob sua guarda arma de fogo, acessório ou munição, de uso permitido, em desacordo com determinação legal ou regulamentar, no interior de sua residência ou dependência desta, ou no seu local de trabalho, desde que seja o titular ou o responsável legal do estabelecimento ou empresa. Pena: detenção de 1 a 3 anos e multa.', '["Posse de arma, acessório ou munição de USO PERMITIDO.","Em desacordo com a lei, na residência, dependência ou local de trabalho do titular.","Detenção de 1 a 3 anos e multa."]'::jsonb, '["POSSE (dentro de casa ou do trabalho) × PORTE (fora): a posse é o art. 12; o porte, o art. 14.","Pena de DETENÇÃO."]'::jsonb, 'Manter em casa pistola de uso permitido sem registro configura posse irregular.', '["Assertiva que aplica o art. 12 a quem anda com a arma na rua erra: seria porte ilegal (art. 14)."]'::jsonb, '[{"termo":"Posse irregular","significado":"Manter arma sem registro dentro de casa ou do local de trabalho."}]'::jsonb, '["Art. 14","Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Omissão de cautela: deixar de observar as cautelas necessárias para impedir que menor de 18 anos ou pessoa portadora de deficiência mental se apodere de arma de fogo que esteja sob sua posse ou que seja de sua propriedade. Pena: detenção de 1 a 2 anos e multa. Nas mesmas penas incorrem o proprietário ou diretor responsável de empresa de segurança e transporte de valores que deixarem de registrar ocorrência policial e de comunicar à Polícia Federal perda, furto, roubo ou outras formas de extravio de arma de fogo, acessório ou munição sob sua guarda, nas primeiras 24 horas depois de ocorrido o fato.', '["Deixar de tomar cautelas para impedir que menor de 18 anos ou pessoa com deficiência mental se apodere da arma.","Detenção de 1 a 2 anos e multa.","Empresa de segurança: não comunicar o extravio à PF em 24 horas."]'::jsonb, '["Crime de omissão (culposo na essência).","Prazo de 24 horas para a empresa comunicar o extravio."]'::jsonb, 'O pai deixa a arma ao alcance do filho menor, que se apodera dela.', '["Assertiva que exige que o menor use a arma para configurar o art. 13 erra: basta a omissão de cautela e o apoderamento."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Porte ilegal de arma de fogo de uso permitido: portar, deter, adquirir, fornecer, receber, ter em depósito, transportar, ceder, ainda que gratuitamente, emprestar, remeter, empregar, manter sob guarda ou ocultar arma de fogo, acessório ou munição, de uso permitido, sem autorização e em desacordo com determinação legal ou regulamentar. Pena: reclusão de 2 a 4 anos e multa. O crime é inafiançável, salvo quando a arma de fogo estiver registrada em nome do agente.', '["Tipo misto alternativo com 14 núcleos.","Arma, acessório ou munição de USO PERMITIDO.","Reclusão de 2 a 4 anos e multa.","Inafiançável, salvo arma registrada em nome do agente."]'::jsonb, '["Crime de perigo abstrato: dispensa a demonstração de perigo concreto.","Arma desmuniciada também configura o crime (entendimento do STF e do STJ).","O STF julgou inconstitucional a vedação de fiança e liberdade provisória em ação direta de inconstitucionalidade."]'::jsonb, 'Portar pistola registrada sem porte, na rua, caracteriza o art. 14.', '["Assertiva que exige perigo concreto à incolumidade pública para o art. 14 erra: é crime de perigo abstrato."]'::jsonb, '[{"termo":"Crime de perigo abstrato","significado":"O perigo é presumido pela lei, sem necessidade de prova."}]'::jsonb, '["Art. 12","Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Disparo de arma de fogo: disparar arma de fogo ou acionar munição em lugar habitado ou em suas adjacências, em via pública ou em direção a ela, desde que essa conduta não tenha como finalidade a prática de outro crime. Pena: reclusão de 2 a 4 anos e multa. O crime é inafiançável.', '["Disparar ou acionar munição em lugar habitado, adjacências ou via pública.","Subsidiário: não pode ter finalidade de outro crime.","Reclusão de 2 a 4 anos e multa.","Inafiançável."]'::jsonb, '["Crime SUBSIDIÁRIO: se o disparo visava a outro crime (por exemplo, homicídio), aplica-se este.","Perigo abstrato."]'::jsonb, 'Dar tiros para o alto numa rua movimentada, sem intenção de ferir ninguém, é disparo de arma de fogo.', '["Assertiva que aplica o art. 15 mesmo quando o disparo visava matar alguém erra: o tipo é subsidiário."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Posse ou porte ilegal de arma de fogo de uso restrito: possuir, deter, portar, adquirir, fornecer, receber, ter em depósito, transportar, ceder, emprestar, remeter, empregar, manter sob guarda ou ocultar arma de fogo, acessório ou munição de uso restrito, sem autorização. Pena: reclusão de 3 a 6 anos e multa. Nas mesmas penas incorre quem suprime ou altera marca, numeração ou sinal de identificação; modifica as características da arma para torná-la equivalente a de uso proibido ou restrito ou para induzir a erro autoridade, perito ou juiz; possui, detém, fabrica ou emprega artefato explosivo ou incendiário sem autorização; porta, possui, adquire, transporta ou fornece arma com numeração raspada, suprimida ou adulterada; vende, entrega ou fornece arma, acessório, munição ou explosivo a criança ou adolescente; e produz, recarrega ou recicla, sem autorização, ou adultera munição ou explosivo. Se envolver arma de uso proibido, a pena é reclusão de 4 a 12 anos.', '["Posse e porte de arma, acessório ou munição de USO RESTRITO: reclusão de 3 a 6 anos e multa.","§1º: arma raspada ou adulterada; artefato explosivo; venda a criança ou adolescente; recarga de munição.","§2º: arma de USO PROIBIDO: reclusão de 4 a 12 anos."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.964, de 2019 (Pacote Anticrime); o §2º elevou a pena para arma de uso proibido.","Equiparado a hediondo quando o objeto é arma de uso PROIBIDO (parágrafo único do art. 1º da Lei dos Crimes Hediondos).","Posse e porte de uso restrito: MESMA pena (não distingue posse de porte)."]'::jsonb, 'Quem guarda em casa um fuzil de uso restrito sem autorização responde pelo art. 16.', '["Assertiva que aplica ao uso restrito a pena de detenção do art. 12 erra: é reclusão de 3 a 6 anos."]'::jsonb, '[]'::jsonb, '["Art. 14","Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comércio ilegal de arma de fogo: adquirir, alugar, receber, transportar, conduzir, ocultar, ter em depósito, desmontar, montar, remontar, adulterar, vender, expor à venda, ou de qualquer forma utilizar, em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, arma de fogo, acessório ou munição, sem autorização. Pena: reclusão de 6 a 12 anos e multa. Equipara-se à atividade comercial ou industrial qualquer forma de prestação de serviços, fabricação ou comércio irregular ou clandestino, inclusive o exercido em residência. Incorre na mesma pena quem vende ou entrega arma, acessório ou munição, sem autorização, a agente policial disfarçado, quando presentes elementos probatórios razoáveis de conduta criminal preexistente.', '["Condutas no exercício de atividade comercial ou industrial.","Reclusão de 6 a 12 anos e multa.","Equipara-se: comércio clandestino, mesmo em residência.","Venda a policial disfarçado, com elementos de conduta preexistente."]'::jsonb, '["ATUALIZAÇÃO: pena elevada pela Lei nº 13.964, de 2019; §2º incluído (policial disfarçado).","Exige a atividade COMERCIAL ou industrial."]'::jsonb, 'Quem vende armas clandestinamente em casa pratica o comércio ilegal.', '["Assertiva que dispensa a atividade comercial ou industrial no art. 17 erra."]'::jsonb, '[]'::jsonb, '["Art. 16","Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tráfico internacional de arma de fogo: importar, exportar, favorecer a entrada ou saída do território nacional, a qualquer título, de arma de fogo, acessório ou munição, sem autorização da autoridade competente. Pena: reclusão de 8 a 16 anos e multa. Incorre na mesma pena quem vende ou entrega arma, acessório ou munição, em operação de importação, sem autorização, a agente policial disfarçado, quando presentes elementos probatórios razoáveis de conduta criminal preexistente.', '["Importar, exportar ou favorecer a entrada ou saída de armas, acessórios ou munições.","Reclusão de 8 a 16 anos e multa.","Venda a agente policial disfarçado em operação de importação."]'::jsonb, '["ATUALIZAÇÃO: pena e §1º dados pela Lei nº 13.964, de 2019.","Competência da JUSTIÇA FEDERAL (tráfico internacional)."]'::jsonb, 'Contrabandear munição de outro país sem autorização é tráfico internacional de arma.', '["Assertiva que fixa a pena do tráfico internacional de arma em 6 a 12 anos erra: é de 8 a 16 anos."]'::jsonb, '[]'::jsonb, '["Art. 17","Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-18'
