insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes previstos nos arts. 17 e 18, a pena é aumentada da metade se a arma de fogo, acessório ou munição forem de uso proibido ou restrito.', '["Comércio ilegal e tráfico internacional: pena aumentada da metade.","Se o objeto for de uso PROIBIDO ou RESTRITO."]'::jsonb, '["Aumento da METADE."]'::jsonb, 'Comerciar ilegalmente fuzis de uso restrito eleva a pena em metade.', '["Assertiva que aplica o aumento do art. 19 aos arts. 14 e 15 erra: vale para os arts. 17 e 18."]'::jsonb, '[]'::jsonb, '["Art. 17","Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes previstos nos arts. 14, 15, 16, 17 e 18, a pena é aumentada da metade se forem praticados por integrante dos órgãos e empresas referidas nos arts. 6º, 7º e 8º, ou se o agente for reincidente específico em crimes dessa natureza.', '["Aumento da metade nos arts. 14 a 18.","Agente integrante dos órgãos e empresas dos arts. 6º, 7º e 8º.","Reincidente específico."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.964, de 2019.","Aumento da metade para o agente que tem DEVER legal de cautela (policial, vigilante)."]'::jsonb, 'Policial que comete crime de comércio ilegal de arma tem a pena aumentada da metade.', '["Assertiva que aplica o aumento do art. 20 ao art. 12 erra: vale para os arts. 14 a 18."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-20'
