select u.id, u.content_sha256, 'Os crimes previstos nos arts. 16, 17 e 18 são insuscetíveis de liberdade provisória. O texto remete a ação direta de inconstitucionalidade.', '["Vedada a liberdade provisória nos arts. 16, 17 e 18."]'::jsonb, '["O STF declarou inconstitucional a vedação absoluta de liberdade provisória."]'::jsonb, 'Texto legal declarado inconstitucional: a liberdade provisória é analisada caso a caso.', '["Assertiva que mantém hoje a vedação absoluta de liberdade provisória do art. 21 erra, à luz da decisão do STF."]'::jsonb, '[]'::jsonb, '["Art. 14, parágrafo único"]'::jsonb, 'under_review', 'claude'
