insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes previstos nos arts. 12, 14 e 16, a pena é aumentada de 2/3 se o crime for praticado em concurso com crime da Lei de Drogas, estiver diretamente ligado ao comércio ilícito de entorpecentes ou o artefato tiver sido utilizado para assegurar o sucesso da mercancia.', '["Arts. 12, 14 e 16: aumento de 2/3.","Concurso com crime da Lei de Drogas, ligação direta ao comércio ilícito de entorpecentes ou uso da arma para assegurar a mercancia."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 15.358, de 2026."]'::jsonb, 'Traficante que porta arma de uso permitido para assegurar a venda de drogas tem a pena aumentada de 2/3.', '["Assertiva que aplica o aumento de 2/3 ao crime de disparo (art. 15) erra: o art. 21-A cita os arts. 12, 14 e 16."]'::jsonb, '[]'::jsonb, '["Lei de Drogas (causas de aumento)"]'::jsonb, 'under_review', 'claude'
