insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A classificação legal, técnica e geral, bem como a definição das armas de fogo e demais produtos controlados, de usos proibidos, restritos, permitidos ou obsoletos e de valor histórico, serão disciplinadas em ato do chefe do Poder Executivo Federal, mediante proposta do Comando do Exército. Todas as munições comercializadas deverão estar em embalagens com código de barras que permita identificar o fabricante e o adquirente. Para os órgãos do art. 6º, somente serão expedidas autorizações de compra de munição com identificação do lote e do adquirente no culote dos projéteis. As armas fabricadas a partir de um ano da publicação conterão dispositivo intrínseco de segurança e de identificação. Instituições de ensino policial, guardas municipais e escolas de formação de segurança privada poderão adquirir insumos e máquinas de recarga.', '["Classificação de uso proibido, restrito, permitido ou obsoleto por ato do chefe do Executivo, a proposta do Exército.","Munição com código de barras.","Identificação do lote e do adquirente no culote para os órgãos do art. 6º.","Dispositivo de segurança e identificação nas armas fabricadas depois de um ano."]'::jsonb, '["A CLASSIFICAÇÃO (permitido, restrito, proibido) vem de ATO DO EXECUTIVO (decreto), com proposta do Exército.","Redação dada pela Lei nº 11.706, de 2008."]'::jsonb, 'Um decreto define quais armas são de uso permitido e quais são de uso restrito.', '["Assertiva que fixa na própria lei a lista de armas de uso restrito erra: a classificação é por ato do chefe do Executivo."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Excetuadas as atribuições do art. 2º (Sinarm), compete ao Comando do Exército autorizar e fiscalizar a produção, exportação, importação, desembaraço alfandegário e o comércio de armas de fogo e demais produtos controlados, inclusive o registro e o porte de trânsito de arma de fogo de colecionadores, atiradores e caçadores.', '["Comando do Exército autoriza e fiscaliza produção, exportação, importação, desembaraço e comércio.","Também registro e porte de trânsito de colecionadores, atiradores e caçadores."]'::jsonb, '["O EXÉRCITO fiscaliza a produção e o comércio; o SINARM (PF) cadastra."]'::jsonb, 'A fábrica de armas é autorizada e fiscalizada pelo Comando do Exército.', '["Assertiva que atribui à Polícia Federal a fiscalização da produção de armas erra: é do Comando do Exército."]'::jsonb, '[]'::jsonb, '["Art. 2º","Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As armas de fogo apreendidas, após a elaboração do laudo pericial e sua juntada aos autos, quando não mais interessarem à persecução penal, serão encaminhadas pelo juiz competente ao Comando do Exército, no prazo de até 48 horas, para destruição ou doação aos órgãos de segurança pública ou às Forças Armadas, na forma do regulamento. As armas e munições apreendidas em decorrência do tráfico de drogas, perdidas em favor da União, devem ser, após perícia que ateste seu bom estado, destinadas com prioridade para os órgãos de segurança pública e do sistema penitenciário da unidade da federação responsável pela apreensão. O Comando do Exército encaminha a relação das armas a serem doadas ao juiz, que determina o perdimento em favor da instituição beneficiada. O Poder Judiciário instituirá instrumentos para o encaminhamento semestral ao Sinarm ou ao Sigma da relação de armas acauteladas em juízo.', '["Arma apreendida sem interesse penal: juiz a envia ao Exército em até 48 horas.","Destino: destruição ou doação a órgãos de segurança ou Forças Armadas.","Armas do tráfico de drogas: prioridade para a segurança pública e o sistema penitenciário do Estado da apreensão.","Relação semestral de armas acauteladas em juízo ao Sinarm ou Sigma."]'::jsonb, '["ATUALIZAÇÃO: caput com redação da Lei nº 13.886, de 2019 (prazo de 48 horas).","Prazo de 48 HORAS."]'::jsonb, 'Após a perícia, o juiz envia a arma ao Exército em 48 horas para destruição ou doação.', '["Assertiva que fixa em 10 dias o prazo de envio da arma ao Exército erra: são 48 horas."]'::jsonb, '[{"termo":"Sigma","significado":"Sistema de Gerenciamento Militar de Armas, do Exército."}]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São vedadas a fabricação, a venda, a comercialização e a importação de brinquedos, réplicas e simulacros de armas de fogo, que com estas se possam confundir. Excetuam-se da proibição as réplicas e os simulacros destinados à instrução, ao adestramento ou à coleção de usuário autorizado, nas condições fixadas pelo Comando do Exército.', '["Vedados brinquedos, réplicas e simulacros que se possam confundir com armas de fogo.","Exceção: instrução, adestramento ou coleção de usuário autorizado."]'::jsonb, '["Exceção condicionada a regras do Comando do Exército."]'::jsonb, 'A venda de pistola de brinquedo idêntica à real é proibida.', '["Assertiva que permite a venda de simulacros indistinguíveis de armas a qualquer pessoa erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao Comando do Exército autorizar, excepcionalmente, a aquisição de armas de fogo de uso restrito. O disposto não se aplica às aquisições dos Comandos Militares. O texto remete a ação direta de inconstitucionalidade.', '["Aquisição de arma de uso restrito: autorização EXCEPCIONAL do Comando do Exército.","Não se aplica às aquisições dos Comandos Militares."]'::jsonb, '["Autorização EXCEPCIONAL."]'::jsonb, 'A compra de arma de uso restrito por particular exige autorização excepcional do Exército.', '["Assertiva que torna regra a autorização de aquisição de arma de uso restrito erra: é excepcional."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedado ao menor de 25 anos adquirir arma de fogo, ressalvados os integrantes das entidades constantes dos incisos I, II, III, V, VI, VII e X do art. 6º.', '["Menor de 25 anos não pode adquirir arma de fogo.","Ressalva: integrantes de certas entidades do art. 6º."]'::jsonb, '["Idade mínima: 25 ANOS (a regra do art. 4º exige, no caso comum, requisitos adicionais)."]'::jsonb, 'Um jovem de 22 anos não pode comprar arma de fogo, salvo se integrar entidade ressalvada.', '["Assertiva que fixa em 21 anos a idade mínima para adquirir arma de fogo erra: são 25 anos."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
