insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As autorizações de porte de armas de fogo já concedidas expirar-se-ão 90 dias após a publicação da Lei. O detentor de autorização com prazo de validade superior a 90 dias poderá renová-la, perante a Polícia Federal, nas condições dos arts. 4º, 6º e 10, no prazo de 90 dias após sua publicação, sem ônus para o requerente.', '["Portes anteriores expiram em 90 dias da publicação da lei.","Renovação na PF, nas condições da lei, sem custo, em 90 dias."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Texto transitório da época da edição do Estatuto.', '["Assertiva que aplica hoje o prazo de 90 dias do art. 29 erra: é dispositivo transitório."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
