insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os possuidores e proprietários de arma de fogo de uso permitido ainda não registrada deveriam solicitar seu registro até o dia 31 de dezembro de 2008, mediante documento de identificação pessoal e comprovante de residência fixa, acompanhados de nota fiscal de compra ou comprovação da origem lícita da posse, ou declaração firmada com as características da arma e a condição de proprietário, dispensados de taxas e de parte das exigências do art. 4º. O proprietário poderia obter, na Polícia Federal, certificado de registro provisório.', '["Regularização do registro até 31 de dezembro de 2008.","Documentos: identificação, residência e nota fiscal ou prova da origem lícita da posse.","Dispensa de taxas e de exigências do art. 4º.","Certificado de registro provisório."]'::jsonb, '["Dispositivo transitório com prazos prorrogados por leis posteriores."]'::jsonb, 'Texto transitório de regularização de armas antigas.', '["Assertiva que mantém aberto indefinidamente o prazo do art. 30 erra: o prazo foi fixado para dezembro de 2008, com prorrogações."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os possuidores e proprietários de armas de fogo adquiridas regularmente poderão, a qualquer tempo, entregá-las à Polícia Federal, mediante recibo e indenização, nos termos do regulamento da Lei.', '["Entrega voluntária à Polícia Federal, a qualquer tempo.","Mediante recibo e indenização."]'::jsonb, '["Para armas adquiridas REGULARMENTE."]'::jsonb, 'O proprietário entrega a arma regular à PF e recebe indenização.', '["Assertiva que restringe a entrega com indenização a um prazo certo erra: pode ser feita a qualquer tempo."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
