insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os possuidores e proprietários de arma de fogo poderão entregá-la, espontaneamente, mediante recibo e, presumindo-se de boa-fé, serão indenizados, na forma do regulamento, ficando extinta a punibilidade de eventual posse irregular da referida arma.', '["Entrega espontânea mediante recibo.","Presunção de boa-fé e indenização.","Extingue-se a punibilidade da posse irregular."]'::jsonb, '["Extingue a punibilidade da POSSE irregular (não abrange outros crimes).","ATUALIZAÇÃO: redação dada pela Lei nº 11.706, de 2008."]'::jsonb, 'O dono de arma sem registro a entrega à PF e fica livre da punição pela posse irregular.', '["Assertiva que extingue a punibilidade de qualquer crime praticado com a arma entregue erra: o benefício é da posse irregular."]'::jsonb, '[]'::jsonb, '["Art. 12","Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-32'
