insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Será aplicada multa de R$ 100.000,00 a R$ 300.000,00, conforme especificar o regulamento, à empresa de transporte aéreo, rodoviário, ferroviário, marítimo, fluvial ou lacustre que deliberadamente, por qualquer meio, faça, promova, facilite ou permita o transporte de arma ou munição sem a devida autorização ou com inobservância das normas de segurança; e à empresa de produção ou comércio de armamentos que realize publicidade para venda, estimulando o uso indiscriminado de armas de fogo, exceto nas publicações especializadas.', '["Multa de R$ 100.000,00 a R$ 300.000,00.","Empresa de transporte que permite o transporte irregular de arma ou munição.","Empresa de armamentos que faz publicidade estimulando o uso indiscriminado."]'::jsonb, '["Sanção ADMINISTRATIVA (multa), e não crime."]'::jsonb, 'A transportadora que facilita o transporte de armas sem autorização sofre multa.', '["Assertiva que trata o art. 33 como crime com pena de reclusão erra: prevê multa administrativa."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os promotores de eventos em locais fechados, com aglomeração superior a 1000 pessoas, adotarão, sob pena de responsabilidade, as providências necessárias para evitar o ingresso de pessoas armadas, ressalvados os eventos garantidos pelo inciso VI do art. 5º da Constituição. As empresas responsáveis pelo transporte internacional e interestadual de passageiros adotarão as providências necessárias para evitar o embarque de passageiros armados.', '["Eventos fechados com mais de 1000 pessoas: providências para evitar o ingresso de pessoas armadas.","Transporte internacional e interestadual: evitar o embarque de passageiros armados.","Ressalva: eventos garantidos pelo art. 5º, VI, da Constituição (cultos religiosos)."]'::jsonb, '["Limite: mais de 1000 pessoas."]'::jsonb, 'O organizador de um show com mais de mil pessoas deve impedir a entrada de pessoas armadas.', '["Assertiva que fixa em 500 o número de pessoas a partir do qual se aplica o art. 34 erra: são mais de 1000."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os dados relacionados à coleta de registros balísticos serão armazenados no Banco Nacional de Perfis Balísticos, que tem por objetivo cadastrar armas de fogo e armazenar características de classe e individualizadoras de projéteis e de estojos de munição deflagrados por arma de fogo. Será constituído pelos registros de elementos de munição deflagrados por armas relacionados a crimes, para subsidiar apurações criminais federais, estaduais e distritais, e gerido pela unidade oficial de perícia criminal. Os dados terão caráter sigiloso, e quem permitir ou promover seu uso para fins diversos responderá civil, penal e administrativamente. É vedada a comercialização da base de dados.', '["Banco Nacional de Perfis Balísticos: dados de projéteis e estojos de munição deflagrados.","Subsidia apurações criminais federais, estaduais e distritais.","Gerido pela unidade oficial de perícia criminal.","Dados sigilosos, com responsabilização por uso indevido.","Vedada a comercialização da base."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.964, de 2019."]'::jsonb, 'O estojo encontrado na cena do crime é comparado com o banco balístico.', '["Assertiva que permite a comercialização da base de dados balísticos erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 2º, X"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'art-34-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibida a comercialização de arma de fogo e munição em todo o território nacional, salvo para as entidades previstas no art. 6º, dispositivo que dependia, para entrar em vigor, de aprovação mediante referendo popular a ser realizado em outubro de 2005. O referendo realizou-se e a proibição não foi aprovada, de modo que o dispositivo não vigora.', '["Previa a proibição da comercialização de armas e munições, salvo para as entidades do art. 6º.","Dependia de referendo popular em outubro de 2005.","Referendo rejeitou a proibição."]'::jsonb, '["O referendo de 2005 REJEITOU a proibição: a comercialização continua permitida, na forma da lei."]'::jsonb, 'A proibição geral do comércio de armas não entrou em vigor.', '["Assertiva que considera em vigor a proibição geral do comércio de armas e munições erra."]'::jsonb, '[{"termo":"Referendo","significado":"Consulta popular sobre lei já aprovada."}]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
