insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Anexo traz a tabela de taxas dos atos administrativos relativos às armas de fogo: o registro (gratuito até 31 de dezembro de 2008 e, depois, R$ 60,00), a renovação do certificado de registro, o registro para empresa de segurança privada e de transporte de valores (R$ 60,00), a renovação para essas empresas (R$ 30,00, R$ 45,00 e R$ 60,00, conforme o período), a expedição de porte de arma de fogo (R$ 1.000,00), a renovação do porte (R$ 1.000,00) e a segunda via de certificado de registro e de porte (R$ 60,00 cada).', '["Registro e renovação: R$ 60,00 a partir de 2009.","Empresas de segurança privada: registro de R$ 60,00 e renovação escalonada.","Porte e renovação do porte: R$ 1.000,00.","Segunda via: R$ 60,00."]'::jsonb, '["Valores previstos na redação da Lei nº 11.706, de 2008; confira atualizações regulamentares."]'::jsonb, 'A expedição do porte federal tem a taxa de R$ 1.000,00.', '["Assertiva que fixa a taxa do porte de arma de fogo em R$ 60,00 erra: é de R$ 1.000,00."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'armas' and u.unit_key = 'anexo-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão punidos, na forma desta Lei, os crimes resultantes de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional.', '["Define o alcance da lei: raça, cor, etnia, religião ou procedência nacional.","Abrange discriminação e preconceito."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 9.459, de 15/05/97 (incluiu etnia, religião e procedência nacional).","Crime de racismo: inafiançável e imprescritível (Constituição, art. 5º, XLII)."]'::jsonb, 'Recusar atendimento a alguém por causa da cor da pele é crime previsto nesta lei.', '["Assertiva que limita a lei à discriminação de cor erra: abrange raça, cor, etnia, religião e procedência nacional."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
